def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = []
    parent = {}

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '#' or visited[r][c]:
            return False
        visited[r][c] = True
        path.append((r, c))
        if (r, c) == goal:
            return True
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if dfs(nr, nc):
                parent[(nr, nc)] = (r, c)
                return True
        path.pop()
        return False

    if dfs(start[0], start[1]):
        # Reconstruct path
        path.reverse()
        current = goal
        while current != start:
            prev = parent[current]
            path[path.index(current)] = prev
            current = prev
        return path
    return []
