        return []
    if start == goal:
        return [start]

    visited = set()
    path = {}
    stack = [start]
    visited.add(start)

    while stack:
        current = stack.pop()
        if current == goal:
            break
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            r, c = current[0] + dr, current[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.' and (r, c) not in visited:
                visited.add((r, c))
                stack.append((r, c))
                path[(r, c)] = current

    if goal not in path:
        return []

    # Reconstruct the path
    current = goal
    path_list = [current]
    while current != start:
        current = path[current]
        path_list.append(current)
    path_list.reverse()
    return path_list
