def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import deque

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check for negative weight cycles (only if s != t)
    if s != t:
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    # If there's a negative cycle that is reachable from s, then t is reachable with negative weight
                    # But we can't return a negative value as the problem says to return -1 if not reachable
                    # So we treat this as t is reachable (though weight is unbounded)
                    dist[v] = -float('inf')

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
