        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = {}

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '#' or visited[r][c]:
            return False
        visited[r][c] = True
        path[(r, c)] = (start[0], start[1]) if (r, c) == start else None
        if (r, c) == goal:
            return True
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if dfs(nr, nc):
                return True
        return False

    if dfs(start[0], start[1]):
        current = goal
        result = [current]
        while current != start:
            current = path[current]
            result.insert(0, current)
        return result
    return []
