from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with priority queue (Dijkstra's alternative using deque for BFS-like approach)
    # This is not Dijkstra's algorithm but a modified BFS that handles weights
    # This works only if all weights are 1, but since weights can be >1, this approach won't work.
    # Actually, without Dijkstra's, the only way is to use Bellman-Ford or BFS with tracking of distances.

    # Bellman-Ford approach
    dist = [float('inf')] * n
    dist[s] = 0

    for _ in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    if dist[t] == float('inf'):
        return -1
    return dist[t]
