def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # BFS with Dijkstra's algorithm using deque for FIFO
    dist = [float('inf')] * n
    dist[s] = 0
    queue = deque([(s, 0)])

    while queue:
        u, d = queue.popleft()
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append((v, dist[v]))

    return dist[t] if dist[t] != float('inf') else -1
