    dist[s] = 0
    visited = [False] * n

    queue = deque([s])
    while queue:
        u = queue.popleft()
        if visited[u]:
            continue
        visited[u] = True
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append(v)

